module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
reg [3:0] counter;
    reg [3:0] index;
    reg [9:0] keypress_array [0:15];
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            index <= 0;
            keypress <= 0;
        end else begin
            if (counter == 20) begin
                keypress <= keypress_array[index];
                counter <= 0;
                index <= index + 1;
            end else begin
                counter <= counter + 1;
            end
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            keypress_array[0] <= 10'b0000000000;
            keypress_array[1] <= 10'b0000000001;
            keypress_array[2] <= 10'b0000000010;
            keypress_array[3] <= 10'b0000000100;
            keypress_array[4] <= 10'b0000001000;
            keypress_array[5] <= 10'b0000010000;
            keypress_array[6] <= 10'b0000100000;
            keypress_array[7] <= 10'b0001000000;
            keypress_array[8] <= 10'b0010000000;
            keypress_array[9] <= 10'b0100000000;
            keypress_array[10] <= 10'b1000000000;
            keypress_array[11] <= 10'b0000000000;
            keypress_array[12] <= 10'b0000000000;
            keypress_array[13] <= 10'b0000000000;
            keypress_array[14] <= 10'b0000000000;
            keypress_array[15] <= 10'b0000000000;
        end
    end
endmodule

