module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);
logic [WIDTH-1:0] dat0;
logic [WIDTH-1:0] dat1;
logic [2:0] state;
logic [2:0] next;
logic t0_ready_d;
logic i0_valid_d;
logic [WIDTH-1:0] i0_data_d;

assign t0_ready = t0_ready_d;
assign i0_data = i0_data_d;
assign i0_valid = i0_valid_d;

always_comb begin
	case (state)
		S0: begin
			i0_valid_d = 0;
			i0_data_d = 0;
			next = S1;
		end
		S1: begin
			i0_valid_d = 0;
			i0_data_d = dat0;
			next = S2;
		end
		S2: begin
			i0_valid_d = 0;
			i0_data_d = dat1;
			next = S3;
		end
		S3: begin
			i0_valid_d = 0;
			i0_data_d = dat0;
			next = S4;
		end
		S4: begin
			i0_valid_d = 1;
			i0_data_d = dat0;
			next = S0;
		end
		default: next = S0;
	endcase
end

always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		state <= S0;
		t0_ready_d <= 0;
		i0_valid_d <= 0;
	end
	else begin
		state <= next;
		t0_ready_d <= t0_ready;
		i0_valid_d <= i0_valid;
	end
end

always_comb begin
	case (state)
		S0: t0_ready = 0;
		S1: t0_ready = 1;
		S2: t0_ready = 1;
		S3: t0_ready = 1;
		S4: t0_ready = 0;
		default: t0_ready = 0;
	endcase
end

always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		dat0 <= 0;
		dat1 <= 0;
	end
	else begin
		if (t0_valid && t0_ready) begin
			dat0 <= t0_data;
		end
		if (i0_valid && i0_ready) begin
			dat1 <= i0_data;
		end
	end
end

endmodule

