module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] total_pixels=640;
parameter [31:0] sync_pulse=10;
parameter [31:0] blanking_horiz=10;
parameter [31:0] blanking_vert=10;
parameter [31:0] hsync_pulse=10;
parameter [31:0] hsync_width=10;
parameter [31:0] vsync_pulse=10;
parameter [31:0] vsync_width=10;
reg [9:0] pixel_x_reg;
reg [9:0] pixel_y_reg;
reg [9:0] hsync_reg;
reg [9:0] vsync_reg;
reg [9:0] hblank_reg;
reg [9:0] vblank_reg;
reg [9:0] hsync_cnt;
reg [9:0] vsync_cnt;
reg [9:0] hblank_cnt;
reg [9:0] vblank_cnt;
  always @(posedge pixel_clk) begin
    if((hsync_cnt == hsync_width)) begin
      hsync_reg <= 1'b0;
    end
    else begin
      hsync_reg <= 1'b1;
    end
    if((vsync_cnt == vsync_width)) begin
      vsync_reg <= 1'b0;
    end
    else begin
      vsync_reg <= 1'b1;
    end
    if((hsync_cnt == hsync_width)) begin
