module clk_div(
input wire clk_i,
output reg clk_o,
output wire [1:0] count_o
); 

reg [1:0] count;
  always @(posedge clk_i) begin
    if(count == 3) begin
      count <= 0;
    end
    else begin
      count <= count + 1;
    end
  end
  assign count_o = count;
  always @(posedge clk_i) begin
    if(count == 0) begin
      clk_o <= 1'b1;
    end
    else if(count == 1) begin
      clk_o <= 1'b0;
    end
    else if(count == 2) begin
      clk_o <= 1'b1;
    end
    else if(count == 3) begin
      clk_o <= 1'b0;
    end
  end
endmodule

