module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire         load_p1;
wire         load_p2;
reg  [1:0]   current_state;
reg  [1:0]   next_state;

assign s_ready = (current_state == ONE || current_state == TWO);
assign m_data  = data_p1;
assign m_valid = (current_state == TWO);

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        current_state <= ZERO;
    end else begin
        if (load_p1) begin
            data_p1 <= s_data;
        end
        if (load_p2) begin
            data_p2 <= data_p1;
        end
        current_state <= next_state;
    end
end


always @(*) begin
    case (current_state)
        ZERO:
            if (s_valid & s_ready)
                next_state <= ONE;
            else
                next_state <= ZERO;
        ONE:
            if (s_valid & s_ready)
                next_state <= TWO;
            else if (m_ready)
                next_state <= ZERO;
            else
                next_state <= ONE;
        TWO:
            if (m_ready)
                next_state <= ZERO;
            else
                next_state <= TWO;
        default:
            next_state <= ZERO;
    endcase
end


assign load_p1 = (current_state == ZERO) & (next_state == ONE);
assign load_p2 = (current_state == ONE) & (next_state == TWO);

endmodule

