module divider 
#(
    parameter WIDTH=23,
    parameter MODULO=6000000
)
(
    input input_clk,
    output output_clk
);
reg [WIDTH-1:0] counter;
    reg output;
    initial begin
        counter = 0;
        output = 0;
    end
    always @(posedge input_clk) begin
        if (counter == MODULO-1) begin
            counter = 0;
            output = ~output;
        end else begin
            counter = counter + 1;
        end
    end
    assign output_clk = output;
endmodule

module sep32_cnt(
    input           clk,
    input           cen,
    input           zero,
    output reg [4:0]    cnt
    );
reg last_zero;
    always @(posedge clk) begin
        if (cen) begin
            if (last_zero == 0 && zero == 1) begin
                cnt <= 1;
            end else begin
                cnt <= cnt + 1;
            end
        end
        last_zero <= zero;
    end
endmodule

module MicrosCounter(
input wire clk_6,
input wire reset,
output wire [31:0] data_out
); 

reg [3:0] prescaler = 0;
reg [31:0] data = 0;
  always @(posedge clk_6) begin
    if((prescaler == 5)) begin
      prescaler <= 0;
      data <= data + 1;
    end
    else begin
      prescaler <= prescaler + 1;
    end
  end
  assign data_out = data;
endmodule

module dec2b2d(input rst, input [9:0]dig, output reg [3:0] uni, dec);
always @(dig) begin
    if (rst) begin
        uni <= 4'b0000;
    end else begin
        if (dig[9]) begin
            uni <= 4'b0001;
        end else if (dig[8]) begin
            uni <= 4'b0010;
        end else if (dig[7]) begin
            uni <= 4'b0011;
        end else if (dig[6]) begin
            uni <= 4'b0100;
        end else if (dig[5]) begin
            uni <= 4'b0101;
        end else if (dig[4]) begin
            uni <= 4'b0110;
        end else if (dig[3]) begin
            uni <= 4'b0111;
        end else if (dig[2]) begin
            uni <= 4'b1000;
        end else if (dig[1]) begin
            uni <= 4'b1001;
        end else if (dig[0]) begin
            uni <= 4'b1010;
        end else begin
            uni <= 4'b1011;
        end
    end
end
endmodule

module timer_1ms(
    input wire clk,
    output reg clk_1ms
);
reg [15:0] cnt = 0;
    always @(posedge clk) begin
        if (cnt == 50000) begin
            cnt <= 0;
            clk_1ms <= ~clk_1ms;
        end else begin
            cnt <= cnt + 1;
        end
    end
    initial begin
        cnt <= 0;
        clk_1ms <= 0;
    end
endmodule

