module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
reg [AW-1:0] cached_addr0;
reg [AW-1:0] cached_addr1;
reg [DW-1:0] cached_data0;
reg [DW-1:0] cached_data1;
reg [DW-1:0] subaddr;
reg          good;
reg          hit0;
reg          hit1;

always @ (posedge clk or posedge rst) begin
    if (rst) begin
        addr_req <= 0;
        cached_addr0 <= 0;
        cached_addr1 <= 0;
        cached_data0 <= 0;
        cached_data1 <= 0;
        subaddr <= 0;
        good <= 0;
        hit0 <= 0;
        hit1 <= 0;
    end else begin
        if (clr) begin
            addr_req <= 0;
            cached_addr0 <= 0;
            cached_addr1 <= 0;
            cached_data0 <= 0;
            cached_data1 <= 0;
            subaddr <= 0;
            good <= 0;
            hit0 <= 0;
            hit1 <= 0;
        end else begin
            if (addr_ok) begin
                addr_req <= {addr[AW-1:0], addr[AW-1:0]};
                if (addr[AW-1:0] == cached_addr0[AW-1:0] && addr[AW-1:0] == cached_addr1[AW-1:0]) begin
                    hit0 <= 1;
                    hit1 <= 1;
                    subaddr <= addr[AW-1:0];
                    good <= 1;
                end else begin
                    hit0 <= 0;
                    hit1 <= 0;
                    subaddr <= 0;
                    good <= 0;
                end
            end
        end
    end
end

always @ (posedge clk or posedge rst) begin
    if (rst) begin
        req <= 0;
        data_ok <= 0;
        sdram_addr <= 0;
        dout <= 0;
    end else begin
        if (we && hit0) begin
            cached_data0 <= din;
            cached_addr0 <= addr_req;
        end
        if (we && hit1) begin
            cached_data1 <= din;
            cached_addr1 <= addr_req;
        end
        if (addr_ok && hit0) begin
            req <= 1;
            data_ok <= 1;
            sdram_addr <= addr_req + offset;
            dout <= cached_data0;
        end else if (addr_ok && hit1) begin
            req <= 1;
            data_ok <= 1;
            sdram_addr <= addr_req + offset;
            dout <= cached_data1;
        end else begin
            req <= 0;
            data_ok <= 0;
            sdram_addr <= 0;
            dout <= 0;
        end
    end
end

endmodule

