module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  assign io_ready = (state == 4'b0000) && io_valid;
  assign tx = (state == 4'b0000) ? data[0] : 1'b0;
  always @(posedge clock) begin
    if (reset) begin
      state <= 4'b0000;
      data <= 8'b00000000;
    end else begin
      if (tick) begin
        if (state == 4'b0000) begin
          if (io_valid) begin
            data <= io_bits;
            state <= 4'b0001;
          end
        end else begin
          if (state == 4'b0001) begin
            data <= {data[6:0], 1'b0};
            state <= 4'b0010;
          end else if (state == 4'b0010) begin
            data <= {data[5:0], 1'b0};
            state <= 4'b0011;
          end else if (state == 4'b0011) begin
            data <= {data[4:0], 1'b0};
            state <= 4'b0100;
          end else if (state == 4'b0100) begin
            data <= {data[3:0], 1'b0};
            state <= 4'b0101;
          end else if (state == 4'b0101) begin
            data <= {data[2:0], 1'b0};
            state <= 4'b0110;
          end else if (state == 4'b0110) begin
            data <= {data[1:0], 1'b0};
            state <= 4'b0111;
          end else if (state == 4'b0111) begin
            data <= {data[0], 1'b0};
            state <= 4'b1000;
          end else if (state == 4'b1000) begin
            data <= 8'b00000000;
            state <= 4'b0000;
          end
        end
      end
    end
  end
endmodule

