module mem_ctl(


    input wire clk,


    input wire [31:0]addr,

    input wire [31:0]data,


    input wire we,


    input wire [1:0]access_width
);
reg [31:0]data_reg;

    always @(posedge clk) begin
        if (we) begin
            case (access_width)
                2'b00: data_reg <= data[7:0];
                2'b01: data_reg <= data[15:0];
                2'b10: data_reg <= data[31:0];
            endcase
        end
    end

    assign data = data_reg;

    always @(posedge clk) begin
        if (we) begin
            case (access_width)
                2'b00: $display("addr: %h, data: %h", addr, data[7:0]);
                2'b01: $display("addr: %h, data: %h", addr, data[15:0]);
                2'b10: $display("addr: %h, data: %h", addr, data[31:0]);
            endcase
        end
    end

endmodule

module data_switch(
	sw_up_en,
	sw_down_en,
	db_down,
	db_up
);


input wire	sw_up_en;
input wire	sw_down_en;

inout wire	[7:0] db_down;

inout wire	[7:0] db_up;
assign db_up = (sw_up_en == 1'b1) ? db_down : 8'bZZZZZZZZ;
assign db_down = (sw_down_en == 1'b1) ? db_up : 8'bZZZZZZZZ;

endmodule

