module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [31:0] H_ACTIVE=1280;
parameter [31:0] H_FRONT_PORCH=16;
parameter [31:0] H_BACK_PORCH=48;
parameter [31:0] H_SYNC_PULSE=96;
parameter [31:0] H_TOTAL=1600;
parameter [31:0] V_ACTIVE=720;
parameter [31:0] V_FRONT_PORCH=10;
parameter [31:0] V_BACK_PORCH=33;
parameter [31:0] V_SYNC_PULSE=2;
parameter [31:0] V_TOTAL=768;
reg [10:0] X = 1280;
reg [10:0] Y = 720;
reg H_SYNC = 1'b1;
reg V_SYNC = 1'b1;
reg DISP_EN = 1'b0;
  always @(posedge CLK, posedge RST) begin
    if(RST == 1'b0) begin
      X <= 1280;
      Y <= 720;
      H_SYNC <= 1'b1;
      V_SYNC <= 1'b1;
      DISP_EN <= 1'b0;
    end else begin
      if(X == 1280) begin
        X <= 0;
        Y <= Y - 1;
      end
      else begin
        X <= X + 1;
      end
      if(Y == 0) begin
        Y <= 720;
        H_SYNC <= 1'b0;
        V_SYNC <= 1'b0;
        DISP_EN <= 1'b1;
      end
      else begin
        H_SYNC <= 1'b1;
        V_SYNC <= 1'b1;
        DISP_EN <= 1'b0;
      end
    end
  end
endmodule

