module sqrt_pipelined
  #(
    parameter
    INPUT_BITS   = 16, 
    OUTPUT_BITS  = INPUT_BITS / 2 + INPUT_BITS % 2 
    )
  (
   input                        clk,        
   input                        reset_n,    
   input                        start,      
   input [INPUT_BITS-1:0]       radicand,   
   output reg                   data_valid, 
   output reg [OUTPUT_BITS-1:0] root        
   );
localparam PIPELINE_STAGES = 10;
  reg [PIPELINE_STAGES-1:0] start_gen;
  reg [PIPELINE_STAGES-1:0] radicand_gen;
  reg [PIPELINE_STAGES-1:0] root_gen;
  reg [PIPELINE_STAGES-1:0] mask_gen;
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      start_gen <= 0;
      radicand_gen <= 0;
      root_gen <= 0;
      mask_gen <= 0;
    end else begin
      start_gen <= start;
      radicand_gen <= radicand;
      root_gen <= root;
      mask_gen <= mask_gen + 1;
    end
  end
  genvar i;
  generate
    for (i = 0; i < PIPELINE_STAGES; i = i + 1) begin : gen
      always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
          start_gen[i] <= 0;
          radicand_gen[i] <= 0;
          root_gen[i] <= 0;
          mask_gen[i] <= 0;
        end else begin
          start_gen[i] <= start_gen[i+1];
          radicand_gen[i] <= radicand_gen[i+1];
          root_gen[i] <= root_gen[i+1];
          mask_gen[i] <= mask_gen[i+1] + 1;
        end
      end
    end
  endgenerate
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      data_valid <= 0;
      root <= 0;
    end else begin
      data_valid <= start_gen[0];
      root <= root_gen[0];
    end
  end
endmodule

