module dhcp_client_m_axis_open_port_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg [DEPTH_BITS-1:0] m_axis_read_index;
reg [DATA_BITS-1:0]  m_axis_dout;
reg                  m_axis_empty_n;
reg                  m_axis_full_n;

reg [DATA_BITS-1:0]  m_axis_din;
reg                  m_axis_write;

reg [DATA_BITS-1:0]  mem [0:DEPTH-1];
always @(posedge clk) begin
    if (aclr) begin
        m_axis_read_index <= '0;
        m_axis_dout       <= '0;
        m_axis_empty_n    <= 1'b1;
        m_axis_full_n     <= 1'b0;
        m_axis_write      <= 1'b0;
    end else begin
        if (write) begin
            m_axis_write <= 1'b1;
            m_axis_din   <= din;
        end
        if (read) begin
            m_axis_read_index <= m_axis_read_index + 1;
            m_axis_dout       <= mem[m_axis_read_index];
        end
        if (write || read) begin
            m_axis_empty_n <= ~m_axis_read_index[DEPTH_BITS-1:0] & m_axis_write;
            m_axis_full_n  <= m_axis_read_index[DEPTH_BITS-1:0] & ~m_axis_write;
        end
    end
end
always @(posedge clk) begin
    if (aclr) begin
        m_axis_din <= '0;
    end else begin
        if (write) begin
            mem[m_axis_read_index] <= m_axis_din;
        end
    end
end
assign dout = m_axis_dout;
assign empty_n = m_axis_empty_n;
assign full_n  = m_axis_full_n;
endmodule

