module pwm(
input wire clk,
input wire rst,
input wire [31:0] duty,
output reg pwm_out
); 

parameter [31:0] PERIOD=8;
reg [31:0] duty_reg;
reg [31:0] counter;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      counter <= 0;
      pwm_out <= 1'b0;
      duty_reg <= duty;
    end else begin
      if((counter < duty_reg)) begin
        pwm_out <= 1'b1;
      end
      else begin
        pwm_out <= 1'b0;
      end
      if((counter == (PERIOD - 1))) begin
        counter <= 0;
        pwm_out <= 1'b0;
        duty_reg <= duty;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
endmodule

module KeyEncoder(Columns, Rows, Clock, Reset, OnesDigit, TensDigit, Found);
	input [3:0] Columns;
	input [3:0] Rows;
	input Clock, Reset;
	output reg [3:0] OnesDigit;
	output reg [3:0] TensDigit;
	output reg Found;
parameter [8:0] KeyMap = 9'b0;
	always @(posedge Clock) begin
		if (Reset) begin
			Found <= 0;
			OneDigit <= 0;
			TensDigit <= 0;
		end else begin
			case (KeyMap)
				9'b00000001: begin
					Found <= 1;
					OneDigit <= Columns;
					TensDigit <= Rows;
				end
				9'b00000010: begin
					Found <= 1;
					OneDigit <= Columns;
					TensDigit <= Rows;
				end
				9'b00000100: begin
					Found <= 1;
					OneDigit <= Columns;
					TensDigit <= Rows;
				end
				9'b00001000: begin
					Found <= 1;
					OneDigit <= Columns;
					TensDigit <= Rows;
				end
				9'b00010000: begin
					Found <= 1;
					OneDigit <= Columns;
					TensDigit <= Rows;
				end
				9'b00100000: begin
					Found <= 1;
					OneDigit <= Columns;
					TensDigit <= Rows;
				end
				9'b01000000: begin
					Found <= 1;
					OneDigit <= Columns;
					TensDigit <= Rows;
				end
				9'b10000000: begin
					Found <= 1;
					OneDigit <= Columns;
					TensDigit <= Rows;
				end
				default: begin
					Found <= 0;
