      a_reg <= {IN_WIDTH{1'b0}};
      b_reg <= {IN_WIDTH{1'b0}};
      ad_reg <= {IN_WIDTH{1'b0}};
      m_reg <= {IN_WIDTH{1'b0}};
      p_reg <= {ACCUM_WIDTH{1'b0}};
    end else if (sample_in_stb) begin
      a_reg <= sample_in_a;
      b_reg <= sample_in_b;
