    if (clear) begin
      ad_reg <= {IN_WIDTH{1'b0}};
      m_reg <= {IN_WIDTH{1'b0}};
    end else if (sample_in_stb) begin
      ad_reg <= a_reg + b_reg;
    end
  end
  always @(posedge clk) begin
