module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire [N-1:0] data_p1_next;
wire [N-1:0] data_p2_next;
reg  [1:0]   state;
reg  [1:0]   next_state;

assign s_ready = (state == ONE || state == TWO);
assign m_data  = data_p1;
assign m_valid = (state == TWO);

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        state   <= ZERO;
    end else begin
        data_p1 <= data_p1_next;
        data_p2 <= data_p2_next;
        state   <= next_state;
    end
end

always @(state or s_valid or s_data) begin
