		2'b10: anodo <= 4'b0100;
		2'b11: anodo <= 4'b1000;
	endcase
end
always @(q_reg)
begin
	case(q_reg[N-2:N])
		2'b00: catodo <= in0;
		2'b01: catodo <= in1;
		2'b10: catodo <= in2;
		2'b11: catodo <= in3;
