module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
parameter CLK_FREQ = 100000000;
  parameter UART_BPS = 115200;
  parameter BPS_CNT = CLK_FREQ / UART_BPS;
  reg [31:0] clk_cnt = 0;
  reg [31:0] tx_cnt = 0;
  reg [7:0] tx_data = 0;
  reg tx_flag = 0;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      tx_flag <= 0;
      tx_data <= 0;
      tx_cnt <= 0;
      clk_cnt <= 0;
    end else begin
      if (uart_en) begin
        tx_flag <= 1;
        tx_data <= uart_din;
        tx_cnt <= 0;
        clk_cnt <= 0;
      end else if (tx_flag) begin
        if (clk_cnt == BPS_CNT) begin
          clk_cnt <= 0;
          if (tx_cnt == 8) begin
            tx_flag <= 0;
            tx_cnt <= 0;
          end else begin
            tx_cnt <= tx_cnt + 1;
          end
        end else begin
          clk_cnt <= clk_cnt + 1;
        end
      end else begin
        if (clk_cnt == BPS_CNT) begin
          clk_cnt <= 0;
          if (tx_cnt == 0) begin
            uart_txd <= 1;
            tx_cnt <= tx_cnt + 1;
          end else if (tx_cnt == 9) begin
            uart_txd <= 0;
            tx_cnt <= tx_cnt + 1;
          end else begin
            uart_txd <= tx_data[tx_cnt - 1];
            tx_cnt <= tx_cnt + 1;
          end
        end else begin
          clk_cnt <= clk_cnt + 1;
        end
      end
    end
  end
endmodule

