module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign enable_wires = {enable_wires[BITS - 2:0], ena};
    always @(posedge clk, posedge rst) begin
        if (rst) begin
            cnt <= {BITS{1'b0}};
        end else begin
            if (ena) begin
                if (updown) begin
                    cnt <= cnt + 1;
                end else begin
                    cnt <= cnt - 1;
                end
            end
        end
    end
    assign out = cnt;
    assign ovf = (cnt == {BITS{1'b1}}) ^ (updown == 1'b0);
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] reg1;
	always @ (reg1)
		begin
			reg1 = reg1 >> 1;
			for (int i = 0; i < 16; i = i + 1)
				begin
					if (reg1[3:0] > 4)
						reg1[3:0] = reg1[3:0] + 3;
					reg1[7:4] = reg1[3:0];
					reg1[11:8] = reg1[7:4];
					reg1[15:12] = reg1[11:8];
					reg1[19:16] = reg1[15:12];
					reg1[23:20] = reg1[19:16];
					reg1[27:24] = reg1[23:20];
					reg1[31:28] = reg1[27:24];
				end
		end
	assign b = reg1[3:0];
	assign s = reg1[7:4];
	assign g = reg1[11:8];
