      if((RD_COMPL_START == 1'b1)) begin
        rd_compl_start <= 1'b1;
        rd_compl_done <= 1'b0;
      end
      if((RD_COMPL_DONE == 1'b1)) begin
        rd_compl_done <= 1'b1;
      end
      if((BM_DONE == 1'b1)) begin
        bm_tag_valid <= 1'b1;
        bm_done <= 1'b1;
      end
      if((RD_COMPL_START == 1'b0 && RD_COMPL_DONE == 1'b1)) begin
        rd_compl_start <= 1'b0;
      end
      if((BM_DONE == 1'b0 && RD_COMPL_DONE == 1'b0)) begin
        rd_compl_done <= 1'b0;
      end
      if((RD_COMPL_START == 1'b0 && RD_COMPL_DONE == 1'b0 && bm_done == 1'b1)) begin
        bm_tag_valid <= 1'b0;
      end
      if((RD_COMPL_START == 1'b0 && RD_COMPL_DONE == 1'b0 && bm_done == 1'b0)) begin
        bm_tag_valid <= 1'b0;
      end
      if((RD_COMPL_START == 1'b0 && RD_COMPL_DONE == 1'b0 && bm_done == 1'b0)) begin
        rd_compl_tag <= {16{1'b0}};
      end
      if((RD_COMPL_START == 1'b1 && RD_COMPL_DONE == 1'b0 && bm_done == 1'b0)) begin
