module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg mainclk;
reg updateclk;
reg capture;
reg update;

always @ (captnupdt or shiftnld or clk)
    begin
        case ({captnupdt, shiftnld})
            2'b10, 2'b11: begin
                mainclk = 1'b0;
                updateclk = clk;
                capture = 1'b1;
                update = 1'b0;
            end
            2'b01: begin
                mainclk = 1'b0;
                updateclk = clk;
                capture = 1'b0;
                update = 1'b0;
            end
            default: begin
                mainclk = clk;
                updateclk = 1'b0;
                capture = 1'b0;
                update = 1'b1;
            end
        endcase
    end

and (mainclk, mainclk, mainclk);
and (updateclk, updateclk, updateclk);
and (capture, capture, capture);
and (update, update, update);

initial
    begin
        mainclk = 1'b0;
        updateclk = 1'b0;
        capture = 1'b0;
        update = 1'b0;
    end

endmodule

module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
    reg [15:0] H_cnt;
    reg Pout_de_w;
    reg Pout_hs_w;
    reg Pout_vs_w;
    reg Rden_w;
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            V_cnt <= 0;
            H_cnt <= 0;
        end else begin
            if (V_cnt == I_v_total - 1) begin
                V_cnt <= 0;
                H_cnt <= H_cnt + 1;
            end else begin
                V_cnt <= V_cnt + 1;
                H_cnt <= H_cnt;
            end
        end
    end
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            Pout_de_w <= 0;
            Pout_hs_w <= 0;
            Pout_vs_w <= 0;
            Rden_w <= 0;
        end else begin
            Pout_de_w <= (H_cnt < I_rd_hres) && (V_cnt < I_rd_vres);
            Pout_hs_w <= (H_cnt < I_h_res - I_h_sync - I_h_bporch);
            Pout_vs_w <= (V_cnt < I_v_res - I_v_sync - I_v_bporch);
            Rden_w <= (H_cnt < I_rd_hres) && (V_cnt < I_rd_vres);
        end
    end
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            O_de <= 0;
            O_hs <= 0;
            O_vs <= 0;
            O_rden <= 0;
        end else begin
            O_de <= Pout_de_w;
            O_hs <= Pout_hs_w;
            O_vs <= Pout_vs_w;
            O_rden <= Rden_w;
        end
    end
    assign O_de = I_hs_pol ? ~O_de : O_de;
    assign O_hs = I_hs_pol ? ~O_hs : O_hs;
    assign O_vs = I_vs_pol ? ~O_vs : O_vs;
endmodule

module alu
    #(parameter WIDTH = 32)
    (   input  [WIDTH - 1 : 0] a,b,
        input  [2 : 0] m,
        output reg [WIDTH - 1 : 0] y,
        output reg zf,      
        output reg cf,      
        output reg of      
    );
always @* begin
        case (m)
            3'b000: y = a + b; cf = y[WIDTH - 1]; of = (a[WIDTH - 1] ^ b[WIDTH - 1]) ^ y[WIDTH - 1];
            3'b001: y = a - b; cf = y[WIDTH - 1]; of = (a[WIDTH - 1] ^ b[WIDTH - 1]) ^ y[WIDTH - 1];
            3'b010: y = a & b; of = 0;
            3'b011: y = a | b; of = 0;
            3'b100: y = a ^ b; of = 0;
            3'b101: y = a; of = 0;
            3'b110: y = b; of = 0;
            3'b111: y = 0; of = 0;
        endcase
        zf = (y == 0);
    end
endmodule

