module DFF_en2(clk ,nRST, en, D, Q);
input wire [n-1:0] D;
input wire en;
input wire clk;
input wire nRST;
output reg [n-1:0] Q;
parameter [31:0] n=32;
always @(posedge clk or negedge nRST) begin
	if(!nRST) begin
		Q <= 0;
	end
	else if(en) begin
		Q <= D;
	end
	else begin
		Q <= 0;
	end
end
endmodule

module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg [DEPTH_BITS-1:0] index;
reg [DEPTH-1:0]      mem [0:DEPTH-1];
reg                  empty;
reg                  full;

assign empty_n = ~empty;
assign full_n  = ~full;
assign dout    = mem[index];

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        index   <= 0;
        empty   <= 1;
        full    <= 0;
    end else begin
        if (write) begin
            if (full) begin
                empty   <= 1;
                full    <= 0;
            end
            mem[index] <= din;
            index     <= (index + 1) % DEPTH;
            if (empty) begin
                empty   <= 0;
                full    <= 1;
            end
        end
        if (read) begin
            if (empty) begin
                empty   <= 0;
                full    <= 1;
            end
            mem[index] <= din;
            index     <= (index + 1) % DEPTH;
            if (full) begin
                empty   <= 1;
                full    <= 0;
            end
        end
    end
end

endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
);
reg [31:0] timer;
reg pre;
always @(posedge clk) begin
    if (timer == 32'd1000000) begin
        if (btn_input == pre) begin
            btn_output <= btn_input;
        end
        timer <= 0;
        pre <= btn_input;
    end
    else begin
        timer <= timer + 1;
    end
end
endmodule

