module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
localparam  IDLE = 2'b00;
  localparam  READY = 2'b01;
  localparam  RELEASE = 2'b10;

  reg [31:0] r_count;
  reg        r_state;
  reg        r_ppfifo_rdy;
  reg        r_ppfifo_act;
  reg        r_ppfifo_stb;
  reg [23:0] r_ppfifo_data;

  assign o_ppfifo_clk = clk;
  assign o_ppfifo_act = r_ppfifo_act;
  assign o_ppfifo_stb = r_ppfifo_stb;
  assign o_ppfifo_data = r_ppfifo_data;

  always @(posedge clk) begin
    if (rst) begin
      r_count <= 0;
      r_state <= IDLE;
      r_ppfifo_rdy <= 0;
      r_ppfifo_act <= 0;
      r_ppfifo_stb <= 0;
      r_ppfifo_data <= 0;
    end else begin
      case (r_state)
        IDLE: begin
          if (i_ppfifo_rdy[0]) begin
            r_state <= READY;
            r_ppfifo_rdy <= 0;
          end
        end
        READY: begin
          if (i_h_blank) begin
            r_count <= 0;
            r_ppfifo_rdy <= 0;
            r_ppfifo_act <= 0;
            r_ppfifo_stb <= 0;
            r_ppfifo_data <= 0;
          end else if (i_v_sync) begin
            r_count <= 0;
            r_ppfifo_rdy <= 0;
            r_ppfifo_act <= 0;
            r_ppfifo_stb <= 0;
            r_ppfifo_data <= 0;
          end else if (i_data_en) begin
            r_count <= r_count + 1;
            if (r_count < i_ppfifo_size) begin
              r_ppfifo_rdy <= 1;
              r_ppfifo_act <= 1;
              r_ppfifo_stb <= 1;
              r_ppfifo_data <= i_rgb;
            end else begin
              r_ppfifo_rdy <= 0;
              r_ppfifo_act <= 0;
              r_ppfifo_stb <= 0;
              r_ppfifo_data <= 0;
            end
          end else begin
            r_ppfifo_rdy <= 0;
            r_ppfifo_act <= 0;
            r_ppfifo_stb <= 0;
            r_ppfifo_data <= 0;
          end
        end
        RELEASE: begin
          r_count <= 0;
          r_ppfifo_rdy <= 0;
          r_ppfifo_act <= 0;
          r_ppfifo_stb <= 0;
          r_ppfifo_data <= 0;
        end
      endcase
    end
  end

endmodule

