module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter INSERT_REGISTER = 1;
 parameter DATA_WIDTH = 1;

 always @(posedge clock or negedge resetn) begin
  if (!resetn) begin
    o_datain_stall <= 1'b0;
    o_dataout_valid <= 1'b0;
  end else begin
    o_datain_stall <= i_dataout_stall;
    o_dataout_valid <= i_datain_valid;
    o_dataout <= i_datain;
  end
 end

endmodule

module NOR_GATE(
input wire A,
input wire B,
output wire C
); 

assign C =  ~(A | B);
endmodule

module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg	[6:0]	data_reg;
	reg	data_regnum;
	reg	data_out_sign;
	reg	data_out;

	always @(negedge clk or negedge rst_n) begin
		if (!rst_n) begin
			data_reg <= 0;
			data_regnum <= 0;
			data_out_sign <= 0;
			data_out <= 0;
		end else begin
			if (data_in_sign) begin
				data_reg <= data_reg + data_in;
				data_regnum <= data_regnum + 1;
			end
			if (data_valid) begin
				data_out_sign <= 1;
				data_out <= data_out + 1;
			end
			if (data_regnum == 8) begin
				if (data_reg == 28 || data_reg == 36) begin
					data_ok <= 1;
				end else begin
					data_ok <= 0;
				end
			end
		end
	end
endmodule

module clk_div(
input wire clk_100MHz,
input wire reset,
output wire clk_100Hz
); 

reg [31:0] ticks = 499999;
reg clk_out = 1'b0;
  always @(posedge clk_100MHz, posedge reset) begin
    if((reset == 1'b1)) begin
      ticks <= 499999;
      clk_out <= 1'b0;
    end else begin
      ticks <= ticks + 1;
      if((ticks == 0)) begin
        clk_out <=  ~clk_out;
      end
    end
  end
  assign clk_100Hz = clk_out;
endmodule

module iiitb_freqdiv(en,clkin,n,clkout);
input clkin;
input [3:0]n;
input en;
output clkout;
reg [3:0]pc,nc;
always @(posedge clkin or negedge en)
begin
if(en)
begin
pc<=pc+1;
nc<=nc+1;
end
else
begin
pc<=0;
nc<=0;
end
end
assign clkout=(pc==n/2)?1'b1:((nc==(n/2)+1)?1'b0:1'b0);
endmodule

module subs(
