	if (MR) begin
		counter <= 0;
		Timeout <= 0;
	end else begin
		if (counter == Divider) begin
			Timeout <= 1;
		end else begin
			Timeout <= 0;
		end
		counter <= counter + 1;
	end
end
endmodule

