module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg  [1:0]   load_p1;
reg  [1:0]   load_p2;
reg  [1:0]   load_p1_from_p2;

wire         s_ready_in;
wire [N-1:0] s_data_in;
wire         s_valid_in;
wire         s_ready_out;
wire [N-1:0] m_data_out;
wire         m_valid_out;

toe_m_axis_rx_data_rsp_metadata_reg_slice_logic #(.N(N))  logic_slice (
    .clk,
    .reset,

    .s_data(s_data_in),
    .s_valid(s_valid_in),
    .s_ready(s_ready_in),

    .m_data(m_data_out),
    .m_valid(m_valid_out),
    .m_ready(m_ready)
);

assign s_ready = s_ready_out;
assign m_data  = m_data_out;
assign m_valid = s_valid_in & s_ready_in;

assign s_data_in  = data_p1;
assign s_valid_in = load_p1_from_p2;
assign s_ready_in = load_p2;

assign m_valid_out = load_p1;

assign s_ready_out = load_p2;

assign load_p1 = {load_p1[0], ONE};
assign load_p2 = {load_p2[0], s_valid_in & s_ready_in};

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        load_p1 <= ZERO;
        load_p2 <= ZERO;
        load_p1_from_p2 <= ZERO;
    end else begin
        if (load_p1 == ONE) begin
            data_p1 <= s_data_in;
            load_p1 <= ZERO;
        end
        if (load_p2 == ONE) begin
            data_p2 <= data_p1;
            load_p2 <= ZERO;
        end
        if (load_p1_from_p2 == ONE) begin
            data_p1 <= data_p2;
            load_p1_from_p2 <= ZERO;
        end
    end
end

endmodule

module Incer #(
    parameter DATA_WIDTH = 8
)
(clk,arstn,din,dout,mode);

input clk;
input arstn;
input mode;
input [DATA_WIDTH-1:0]din;
output [DATA_WIDTH-1:0]dout;
parameter ADD_STATE = 1'b0;
parameter INC_STATE = 1'b1;

reg [DATA_WIDTH-1:0]counter;
reg [1:0]state;
reg [1:0]next_state;

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        counter <= 0;
        state <= ADD_STATE;
    end
    else
    begin
        next_state <= state;
        case (state)
            ADD_STATE: begin
                if(mode)
                    counter <= din + 2;
                else
                    counter <= din + 1;
                next_state <= INC_STATE;
            end
            INC_STATE: begin
                if(mode)
                    next_state <= ADD_STATE;
                else
                    counter <= counter + 1;
            end
        endcase
    end
end

assign dout = counter;

endmodule

