module udpAppMux_txLengthNetwork_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg [DATA_BITS-1:0] mem [0:DEPTH-1];
reg [DEPTH_BITS-1:0] index;

assign empty_n = (index == 0);
assign full_n  = (index == DEPTH-1);
assign dout    = mem[index];

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        index <= 0;
    end else if (write) begin
        mem[index] <= din;
        index <= index + 1;
    end
end

genvar i;
generate
    for (i = 0; i < DEPTH; i = i + 1) begin : shift_reg
        reg [DATA_BITS-1:0] s_dout;
        always @(posedge clk or posedge aclr) begin
            if (aclr) begin
                s_dout <= 0;
            end else if (read) begin
                s_dout <= mem[i];
            end
        end
        assign mem[i] = s_dout;
    end
endgenerate

endmodule

module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);
localparam   S_IDLE = 0;
    localparam   S_RUN = 1;
    localparam   S_DONE = 2;

    reg   [1:0]          state;
    reg   [DWIDTH-1:0]   cnt_val;
    reg   [DWIDTH-1:0]   cnt_val_n;
    reg                  run;
    reg                  done;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            cnt_val <= 0;
            run <= 0;
            done <= 0;
        end else begin
            state <= state_n;
            cnt_val <= cnt_val_n;
            run <= run_o;
            done <= done_o;
        end
    end

    always @(*) begin
        state_n = state;
        cnt_val_n = cnt_val;
        run_o = 0;
        done_o = 0;
        case (state)
            S_IDLE: begin
                if (start_i) begin
                    state_n = S_RUN;
                    cnt_val_n = cnt_val_i;
                end
            end
            S_RUN: begin
                if (cnt_val == cnt_i) begin
                    state_n = S_DONE;
                    run_o = 1;
                end
            end
            S_DONE: begin
                state_n = S_IDLE;
                done_o = 1;
            end
        endcase
    end

endmodule

