module sparc_ifu_esl_lfsr
(
    input               clk,
    input               rst_n,


    input [15:0]        lfsr_seed,
    input               lfsr_ld,


    input               lfsr_step,


    output reg [15:0]   lfsr_state_f,


    output reg          lfsr_out_f
);
localparam LFSR_WIDTH = 16;
    localparam LFSR_FEEDBACK_TAPS = 16'b0000000000000001;

    reg [LFSR_WIDTH-1:0] lfsr_state;
    reg [LFSR_WIDTH-1:0] lfsr_next;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lfsr_state <= 0;
        end else begin
            if (lfsr_ld) begin
                lfsr_state <= lfsr_seed;
            end else begin
                lfsr_state <= lfsr_next;
            end
        end
    end

    always @(lfsr_state or lfsr_step) begin
        lfsr_next = lfsr_state;
        lfsr_next[LFSR_WIDTH-1] = lfsr_state[LFSR_WIDTH-1] ^ lfsr_state[LFSR_WIDTH-2] ^ lfsr_state[LFSR_WIDTH-3] ^ lfsr_state[LFSR_WIDTH-4] ^ lfsr_state[LFSR_WIDTH-5] ^ lfsr_state[LFSR_WIDTH-6] ^ lfsr_state[LFSR_WIDTH-7] ^ lfsr_state[LFSR_WIDTH-8] ^ lfsr_state[LFSR_WIDTH-9] ^ lfsr_state[LFSR_WIDTH-10] ^ lfsr_state[LFSR_WIDTH-11] ^ lfsr_state[LFSR_WIDTH-12] ^ lfsr_state[LFSR_WIDTH-13] ^ lfsr_state[LFSR_WIDTH-14] ^ lfsr_state[LFSR_WIDTH-15] ^ lfsr_state[LFSR_WIDTH-16];
        if (lfsr_step) begin
            lfsr_next[LFSR_WIDTH-1] = 0;
        end
    end

    always @(lfsr_state or lfsr_step) begin
        lfsr_out_f = lfsr_state[LFSR_WIDTH-1];
    end

endmodule

module mux4_1n (
    input EN_n,
    input A, B,
    input D0, D1, D2, D3,
    output Y
);
reg Y_reg;
    wire [1:0] S;
    assign S = {A, B};
    always @ (EN_n or D0 or D1 or D2 or D3 or A or B) begin
        if (!EN_n) begin
            Y_reg <= 1'b0;
        end else begin
            case (S)
                2'b00: Y_reg <= D0;
                2'b01: Y_reg <= D1;
                2'b10: Y_reg <= D2;
                2'b11: Y_reg <= D3;
            endcase
        end
    end
    assign Y = Y_reg;
endmodule

