module display(
    input sysclk,
    input [7:0] anodes,
    output reg shift = 0,
    output reg latch = 0,
    output reg data = 0
    );
reg [3:0] step_count = 0;
    always @(posedge sysclk) begin
        if (anodes != 8'b0) begin
            step_count <= 0;
            shift <= 1;
            latch <= 0;
            data <= anodes[0];
        end
        else if (step_count == 0) begin
            shift <= 1;
            latch <= 0;
            data <= anodes[1];
        end
        else if (step_count == 1) begin
            shift <= 1;
            latch <= 0;
            data <= anodes[2];
        end
        else if (step_count == 2) begin
            shift <= 1;
            latch <= 0;
            data <= anodes[3];
        end
        else if (step_count == 3) begin
            shift <= 1;
            latch <= 0;
            data <= anodes[4];
        end
        else if (step_count == 4) begin
            shift <= 1;
            latch <= 0;
            data <= anodes[5];
        end
        else if (step_count == 5) begin
            shift <= 1;
            latch <= 0;
            data <= anodes[6];
        end
        else if (step_count == 6) begin
            shift <= 1;
            latch <= 0;
            data <= anodes[7];
        end
        else if (step_count == 7) begin
            shift <= 0;
            latch <= 1;
            data <= 0;
        end
        else begin
            shift <= 0;
            latch <= 0;
            data <= 0;
        end
        step_count <= step_count + 1;
    end
endmodule

