module button_pulse 
#(
    parameter MAX_COUNT = 8,    
    parameter DEC_COUNT = 2,    
    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);
reg [7:0] comp = MAX_COUNT - 1;
    reg [7:0] count = 0;
    assign pulse = (count == 0 && button) ? 1'b1 : 1'b0;
    always @(posedge clk) begin
        if (clk_en) begin
            if (reset) begin
                comp <= MAX_COUNT - 1;
                count <= 0;
            end
            else if (button) begin
                if (comp == 0) begin
                    count <= count + 1;
                    comp <= MAX_COUNT - 1;
                end
                else begin
                    comp <= comp - DEC_COUNT;
                end
            end
            else begin
                comp <= MAX_COUNT - 1;
                count <= 0;
            end
        end
    end
endmodule

