module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b00,
    ONE  = 2'b01,
    TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg  [1:0]   state, next;
reg  load_p1, load_p2, load_p1_from_p2;
wire         s_ready_t;

assign s_ready = s_ready_t;
assign m_data  = data_p1;
assign m_valid = load_p1_from_p2;

assign s_ready_t = (state == ONE) ? 1'b1 : 1'b0;

always @(posedge clk) begin
    if (reset == 1'b1) begin
        state <= ZERO;
        load_p1 <= 1'b0;
        load_p2 <= 1'b0;
    end else begin
        state <= next;
        load_p1 <= 1'b0;
        load_p2 <= 1'b0;
        if (load_p1_from_p2 == 1'b1) begin
            data_p1 <= data_p2;
            load_p1 <= 1'b1;
        end
    end
end

always @(state or s_valid or m_ready) begin
    case (state)
        ZERO: begin
            next = s_valid ? ONE : ZERO;
            load_p1_from_p2 = 1'b0;
        end
        ONE: begin
            next = s_valid ? TWO : ZERO;
            load_p1_from_p2 = 1'b0;
        end
        TWO: begin
            next = s_valid ? ONE : ZERO;
            load_p1_from_p2 = 1'b1;
        end
        default: begin
            next = ZERO;
        end
    endcase
end

endmodule

