module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;
parameter clog2_FIFO_DEPTH = $clog2(FIFO_DEPTH);

reg [clog2_FIFO_DEPTH-1:0]wr_ptr;
reg [clog2_FIFO_DEPTH-1:0]rd_ptr;

reg [clog2_FIFO_DEPTH-1:0]wr_ptr_next;
reg [clog2_FIFO_DEPTH-1:0]rd_ptr_next;

reg [DATA_WIDTH-1:0]mem [0:FIFO_DEPTH-1];

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        wr_ptr <= 0;
        rd_ptr <= 0;
    end
    else
    begin
        if(wrreq)
        begin
            wr_ptr_next <= wr_ptr + 1;
            if(wr_ptr_next == FIFO_DEPTH-1)
                wr_ptr_next <= 0;
        end
        else
            wr_ptr_next <= wr_ptr;
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        rd_ptr <= 0;
    end
    else
    begin
        if(rdreq)
        begin
            rd_ptr_next <= rd_ptr + 1;
            if(rd_ptr_next == FIFO_DEPTH-1)
                rd_ptr_next <= 0;
        end
        else
            rd_ptr_next <= rd_ptr;
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        usedw <= 0;
    end
    else
    begin
        usedw <= wr_ptr_next - rd_ptr_next;
    end
end

assign empty = (wr_ptr == rd_ptr);
assign full = (wr_ptr == rd_ptr + FIFO_DEPTH-1);

assign data_out = mem[rd_ptr];

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        mem[wr_ptr] <= 0;
    end
    else
    begin
        if(wrreq)
        begin
            mem[wr_ptr] <= data_in;
        end
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        wr_ptr <= 0;
    end
    else
    begin
        wr_ptr <= wr_ptr_next;
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        rd_ptr <= 0;
    end
    else
    begin
        rd_ptr <= rd_ptr_next;
    end
end

endmodule

