    initial begin
        $display("Starting testbench");
        for (i = 0; i < 100; i = i + 1) begin
            A = $random;
            B = $random;
            if (A_greater != (A > B)) begin
                $display("Test case %d failed: A > B expected %b, got %b", i, A > B, A_greater);
                error = error + 1;
            end
            if (A_equal != (A == B)) begin
                $display("Test case %d failed: A == B expected %b, got %b", i, A == B, A_equal);
