            end
            if (A_less != (A < B)) begin
                $display("Test case %d failed: A < B expected %b, got %b", i, A < B, A_less);
                error = error + 1;
            end
        end
        if (error == 0) begin
            $display("All %d test cases passed", i);
        end else begin
            $display("Failed %d test cases", error);
        end
        $finish;
    end
