module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );
localparam SEED = 32'h00000001;
  reg [31:0] M_x, M_y, M_z, M_w, M_w_d;
  reg [31:0] t;
  always @(posedge clk) begin
    if (rst) begin
      M_x <= SEED;
      M_y <= SEED;
      M_z <= SEED;
      M_w <= SEED;
      M_w_d <= SEED;
    end else begin
      M_x <= M_x_d;
      M_y <= M_y_d;
      M_z <= M_z_d;
      M_w <= M_w_d;
      M_w_d <= M_w_q;
    end
  end
  always @(M_x, M_y, M_z, M_w) begin
    M_x_d <= M_x;
    M_y_d <= M_y;
    M_z_d <= M_z;
    M_w_d <= M_w;
    t = M_x & M_y;
    M_w_q <= {M_z, M_w} ^ t;
  end
  always @(posedge clk) begin
    if (rst) begin
      M_w <= SEED;
    end else if (next) begin
      M_w <= M_w_d;
    end
  end
  assign num = M_w_q;
endmodule

