module clock_divider(
input wire clock,
output wire clock_div
); 

parameter [31:0] input_freq=1000000;
parameter [31:0] output_freq=500000;
reg [31:0] counter = 0;
reg clock_signal = 1'b0;
  always @(posedge clock) begin
    if(counter == (input_freq / output_freq)) begin
      counter <= 0;
      clock_signal <=  ~clock_signal;
    end
    else begin
      counter <= counter + 1;
    end
  end
  assign clock_div = clock_signal;
endmodule

