module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg red,yellow,green;
reg [2:0] state;


always @(posedge clk or posedge reset)
begin
	if (reset)
	begin
		state <= 3'b000;
		red <= 1'b0;
		yellow <= 1'b0;
		green <= 1'b0;
	end
	else
	begin
		case (state)
			3'b000: begin
				red <= 1'b1;
				yellow <= 1'b0;
				green <= 1'b0;
				state <= 3'b001;
			end
			3'b001: begin
				red <= 1'b0;
				yellow <= 1'b1;
				green <= 1'b0;
				state <= 3'b010;
			end
			3'b010: begin
				red <= 1'b0;
				yellow <= 1'b0;
				green <= 1'b1;
				state <= 3'b000;
			end
			3'b011: begin
				red <= 1'b0;
				yellow <= 1'b1;
				green <= 1'b0;
				state <= 3'b010;
			end
			default: begin
				red <= 1'b0;
				yellow <= 1'b0;
				green <= 1'b0;
				state <= 3'b000;
			end
		endcase
	end
end
endmodule

