module grid_CloseID(

input					rsi_MRST_reset,	
input					csi_MCLK_clk,


output	[31:0]	avs_CloseID_readdata,
input		[1:0]		avs_CloseID_address,
input					avs_CloseID_read,
output				avs_CloseID_waitrequest
);
reg	[31:0]	out_data;

assign avs_CloseID_readdata = out_data;
assign avs_CloseID_waitrequest = 0;

always @ (avs_CloseID_address)
begin
	case (avs_CloseID_address)
		2'b00: out_data = 32'h00000000;
		2'b01: out_data = 32'hA5A5A5A5;
		2'b10: out_data = 32'h00000000;
		2'b11: out_data = 32'h5A5A5A5A;
	endcase
end

endmodule

