module zsignals
(
  input wire clk,
  input wire zpos,
  input wire rst_n,
  input wire iorq_n,
  input wire mreq_n,
  input wire m1_n,
  input wire rfsh_n,
  input wire rd_n,
  input wire wr_n,
  output wire rst,
  output wire m1,
  output wire rfsh,
  output wire rd,
  output wire wr,
  output wire iorq,
  output wire mreq,
  output wire rdwr,
  output wire iord,
  output wire iowr,
  output wire iordwr,
  output wire memrd,
  output wire memwr,
  output wire memrw,
  output wire opfetch,
  output wire intack,
  output wire iorq_s,
  output wire mreq_s,
  output wire iord_s,
  output wire iowr_s,
  output wire iordwr_s,
  output wire memrd_s,
  output wire memwr_s,
  output wire memrw_s,
  output wire opfetch_s
);
reg iorq_r, iorq_r_s;
  reg mreq_r, mreq_r_s;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      iorq_r <= 1'b0;
      mreq_r <= 1'b0;
    end else begin
      if (zpos) begin
        iorq_r <= iorq_n;
        mreq_r <= mreq_n;
      end
    end
  end
  assign iorq = iorq_r;
  assign iorq_s = iorq_r_s;
  assign mreq = mreq_r;
  assign mreq_s = mreq_r_s;
  reg rd_r, rd_r_s;
  reg wr_r, wr_r_s;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rd_r <= 1'b0;
      wr_r <= 1'b0;
    end else begin
      if (zpos) begin
        rd_r <= rd_n;
        wr_r <= wr_n;
      end
    end
  end
  assign rd = rd_r;
  assign rd_s = rd_r_s;
  assign wr = wr_r;
  assign wr_s = wr_r_s;
  reg iord_r, iord_r_s;
  reg iowr_r, iowr_r_s;
  reg iordwr_r, iordwr_r_s;
  reg memrd_r, memrd_r_s;
  reg memwr_r, memwr_r_s;
  reg memrw_r, memrw_r_s;
  reg opfetch_r, opfetch_r_s;
  reg intack_r, intack_r_s;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      iord_r <= 1'b0;
      iowr_r <= 1'b0;
      iordwr_r <= 1'b0;
      memrd_r <= 1'b0;
      memwr_r <= 1'b0;
      memrw_r <= 1'b0;
      opfetch_r <= 1'b0;
      intack_r <= 1'b0;
    end else begin
      if (zpos) begin
        iord_r <= iord_n;
        iowr_r <= iowr_n;
        iordwr_r <= iordwr_n;
        memrd_r <= memrd_n;
        memwr_r <= memwr_n;
        memrw_r <= memrw_n;
        opfetch_r <= opfetch_n;
        intack_r <= intack_n;
      end
    end
  end
  assign iord = iord_r;
  assign iord_s = iord_r_s;
  assign iowr = iowr_r;
  assign iowr_s = iowr_r_s;
  assign iordwr = iordwr_r;
  assign iordwr_s = iordwr_r_s;
  assign memrd = memrd_r;
  assign memrd_s = memrd_r_s;
  assign memwr = memwr_r;
  assign memwr_s = memwr_r_s;
  assign memrw = memrw_r;
  assign memrw_s = memrw_r_s;
  assign opfetch = opfetch_r;
  assign opfetch_s = opfetch_r_s;
  assign intack = intack_r;
  assign intack_s = intack_r_s;
endmodule

