module cyclonev_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg mainclk_tmp;
reg updateclk_tmp;
reg capture_tmp;
reg update_tmp;

always @(captnupdt or shiftnld or clk)
begin
    case ({captnupdt, shiftnld, clk})
        3'b000: begin
            mainclk_tmp <= 1'b0;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b0;
            update_tmp <= 1'b0;
        end
        3'b001: begin
            mainclk_tmp <= 1'b0;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b0;
            update_tmp <= 1'b1;
        end
        3'b010: begin
            mainclk_tmp <= 1'b0;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b1;
            update_tmp <= 1'b0;
        end
        3'b011: begin
            mainclk_tmp <= 1'b0;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b1;
            update_tmp <= 1'b1;
        end
        3'b100: begin
            mainclk_tmp <= 1'b1;
            updateclk_tmp <= 1'b1;
            capture_tmp <= 1'b0;
            update_tmp <= 1'b0;
        end
        3'b101: begin
            mainclk_tmp <= 1'b1;
            updateclk_tmp <= 1'b1;
            capture_tmp <= 1'b0;
            update_tmp <= 1'b1;
        end
        3'b110: begin
            mainclk_tmp <= 1'b1;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b1;
            update_tmp <= 1'b0;
        end
        3'b111: begin
            mainclk_tmp <= 1'b1;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b1;
            update_tmp <= 1'b1;
        end
        default: begin
            mainclk_tmp <= 1'b0;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b0;
            update_tmp <= 1'b0;
        end
    endcase
end

assign mainclk = mainclk_tmp & 1'b1;
assign updateclk = updateclk_tmp & 1'b1;
assign capture = capture_tmp & 1'b1;
assign update = update_tmp & 1'b1;

endmodule

