module maxFinder #(parameter numInput=10,parameter inputWidth=16)(
input           i_clk,
input [(numInput*inputWidth)-1:0]   i_data,
input           i_valid,
output reg [31:0]o_data,
output  reg     o_data_valid
);
reg [31:0] maxValue;
reg [31:0] inDataBuffer[(numInput*inputWidth)-1:0];
reg [31:0] counter;
always @(posedge i_clk) begin
    if(i_valid) begin
        counter <= 0;
        o_data_valid <= 0;
    end else begin
        if(counter == (numInput-1)) begin
            o_data_valid <= 1;
            o_data <= counter;
        end
        if(counter < (numInput-1)) begin
            inDataBuffer[counter*inputWidth+inputWidth-1:0] <= i_data[counter*inputWidth+inputWidth-1:0];
            counter <= counter + 1;
        end
    end
end
always @(posedge i_clk) begin
    if(i_valid) begin
        maxValue <= 0;
        counter <= 0;
    end else begin
        if(counter < (numInput-1)) begin
            if(inDataBuffer[counter*inputWidth+inputWidth-1:0] > maxValue) begin
                maxValue <= inDataBuffer[counter*inputWidth+inputWidth-1:0];
                counter <= counter + 1;
            end
        end else begin
            if(inDataBuffer[counter*inputWidth+inputWidth-1:0] > maxValue) begin
                maxValue <= inDataBuffer[counter*inputWidth+inputWidth-1:0];
                counter <= counter + 1;
            end
        end
    end
end
endmodule

