module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
input clk; 
	input startGameEn; 
	input [7:0]user_x; 
	input [6:0]user_y; 
	input [7:0]enemy_x; 
	input [6:0]enemy_y; 
	input [160*120-1:0] enem_grid; 
	output reg [7:0] x; 
	output reg [6:0] y; 
	output reg[2:0] colour;
reg clear;
	always @(posedge clk) begin
		if (startGameEn) begin
			clear <= 1;
			x <= 0;
			y <= 0;
		end
		else begin
			if (clear) begin
				clear <= 0;
				x <= 0;
				y <= 0;
			end
			else begin
				if (x == 160 && y == 120) begin
					x <= 0;
					y <= 0;
				end
				else begin
					if (x == user_x && y == user_y) begin
						colour <= 3;
					end
					else if (x == enemy_x && y == enemy_y) begin
						colour <= 2;
					end
					else if (enem_grid[y*160 + x] == 1) begin
						colour <= 4;
					end
					else begin
						colour <= 0;
					end
					x <= x + 1;
					y <= y + 1;
				end
			end
		end
	end
endmodule

module Start_UP_Handler(
input wire i_CLK,
output wire o_RST
); 

parameter [31:0] g_Clock_Frequency=1000000;
parameter [31:0] g_Initial_Reset_Time=1000000;
reg r_RST;
reg [31:0] r_RST_Counter;
  assign o_RST = r_RST;
  always @(posedge i_CLK) begin
    r_RST_Counter <= r_RST_Counter + 1;
    if(r_RST_Counter == c_Initial_Reset_Clocks) begin
      r_RST <= 1'b0;
    end
    else begin
      r_RST <= 1'b1;
    end
  end
  assign c_Initial_Reset_Clocks = (g_Clock_Frequency * g_Initial_Reset_Time) / 1000000;
endmodule

module sonar(
input clk, rst_n, 
input do_measure,
input sonar_pulse,
output reg [7:0] inches,
output reg sonar_trigger = 0,
output reg READY = 0
);
reg [1:0] state = 0;
reg [31:0] timeCount = 0;
reg [31:0] timeoutCounter = 0;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 0;
        timeCount <= 0;
        timeoutCounter <= 0;
        sonar_trigger <= 0;
        READY <= 0;
    end else begin
        case (state)
            0: begin
                if (do_measure) begin
                    state <= 1;
                    sonar_trigger <= 1;
                end
            end
            1: begin
                if (sonar_pulse) begin
                    state <= 2;
                    timeoutCounter <= 0;
                end
            end
            2: begin
                if (sonar_pulse) begin
                    timeoutCounter <= 0;
                end else begin
                    timeoutCounter <= timeoutCounter + 1;
                    if (timeoutCounter > 1000000) begin
                        state <= 0;
                        timeCount <= 0;
                    end
                end
            end
            3: begin
                timeCount <= timeCount + 1;
                if (sonar_pulse) begin
                    state <= 2;
                    timeoutCounter <= 0;
                end else begin
                    state <= 0;
                    inches <= timeCount * 10 / 17600;
                end
            end
        endcase
        READY <= (state == 0);
    end
end
endmodule

