  input             scan_in1,    
  input             scan_in2,    
  input             scan_in3,    
  input             scan_in4,    
  input             scan_enable, 
  input             test_mode,   
  input      [15:0] W,
  output reg [15:0] S,
  output            scan_out0,   
  output            scan_out1,   
  output            scan_out2,   
  output            scan_out3,   
  output            scan_out4    
);
