module BaudTickGen(
	input clk, enable,
	output tick  
);
parameter ClkFrequency = 100000000;
	parameter Baud = 115200;
	parameter Oversampling = 1;
	
	parameter log2 = $clog2(Baud * Oversampling);
	
	reg [log2-1:0] Acc;
	wire [log2-1:0] Inc = Baud * Oversampling;
	
	always @(posedge clk) begin
		if (enable) begin
			Acc <= Acc + Inc;
		end else begin
			Acc <= 0;
		end
	end
	
	assign tick = Acc >= Inc;
	
endmodule

