module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);
parameter TOTAL_COLUMNS = 1280;
    parameter TOTAL_ROWS = 720;
    parameter ACTIVE_COLUMNS = 640;
    parameter ACTIVE_ROWS = 480;

    reg hsync;
    reg vsync;

    always @(posedge i_clk) begin
        if (o_col_count == TOTAL_COLUMNS) begin
            o_col_count <= 0;
            hsync <= 0;
        end else begin
            o_col_count <= o_col_count + 1;
            hsync <= 1;
        end

        if (o_row_count == TOTAL_ROWS) begin
            o_row_count <= 0;
            vsync <= 0;
        end else begin
            o_row_count <= o_row_count + 1;
            vsync <= 1;
        end
    end

    always @(posedge i_clk) begin
        if (o_col_count == ACTIVE_COLUMNS) begin
            o_col_count <= 0;
            hsync <= 0;
        end else begin
            o_col_count <= o_col_count + 1;
            hsync <= 1;
        end

        if (o_row_count == ACTIVE_ROWS) begin
            o_row_count <= 0;
            vsync <= 0;
        end else begin
            o_row_count <= o_row_count + 1;
            vsync <= 1;
        end
    end

endmodule

