module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 16;
    reg [maxbit-1:0] q_reg, q_next;
    reg f1, f2;
    wire q_add, q_reset;
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 0;
            f1 <= 0;
            f2 <= 0;
        end else begin
            f1 <= button_in;
            f2 <= f1;
            q_reg <= q_next;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_next <= 0;
        end else begin
            q_next <= q_reg + q_add;
        end
    end
    assign q_add = (q_reg == 0) ? 1'b1 : 1'b0;
    assign q_reset = (q_reg == 0) ? 1'b1 : 1'b0;
    always @(q_reg or f1 or f2) begin
        case (q_reg)
            0: out <= 1'b0;
            maxbit-1: out <= 1'b1;
            default: out <= f2;
        endcase
    end
endmodule

