module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output [7 : 0] q
);
reg [7 : 0] mem [15 : 0];
    reg [3 : 0] wp, rp;
    reg w_flag, r_flag;

    always @(posedge clock) begin
        if (sclr) begin
            wp <= 0;
            rp <= 0;
            w_flag <= 0;
            r_flag <= 0;
        end else begin
            if (wrreq) begin
                if (wp == 15) begin
                    wp <= 0;
                    w_flag <= 1;
                end else begin
                    mem[wp] <= data;
                    wp <= wp + 1;
                    w_flag <= 0;
                end
            end
            if (rdreq) begin
                if (rp == 15) begin
                    rp <= 0;
                    r_flag <= 1;
                end else begin
                    q <= mem[rp];
                    rp <= rp + 1;
                    r_flag <= 0;
                end
            end
        end
    end

    always @(posedge clock) begin
        if (sclr) begin
            full <= 0;
            empty <= 1;
        end else begin
            if (w_flag) begin
                full <= 1;
                empty <= 0;
            end else if (r_flag) begin
                full <= 0;
                empty <= 1;
            end else begin
                full <= 0;
                empty <= 0;
            end
        end
    end

endmodule

