always @(posedge clk or negedge rst_l)
    if (!rst_l)
        q <= 0;
    else
        q <= din;

endmodule

module TB_synchro;
reg clk;
	reg dato;
	wire ds;

	Synchro uut(.clk(clk), .dato(dato), .ds(ds));

	initial begin
		clk = 0;
		dato = 0;
	end

	always #10 clk = ~clk;

	always #30 dato = 1;
	always #80 dato = 0;

endmodule

module sr_latch(NQ, Q, S, R);
output Q, NQ;
input S, R;
reg state = 1;

assign NQ = ~Q;

always @(S or R)
begin
    if (S)
        state = 1;
    else if (R)
        state = 0;
end

assign #5 Q = state;
endmodule

