input[DATA_WIDTH - 1:0] if_din;
parameter MEM_STYLE = "shiftreg";
parameter DATA_WIDTH = 32'd1;
parameter ADDR_WIDTH = 32'd2;
parameter DEPTH = 32'd3;

reg[ADDR_WIDTH - 1:0] shiftReg_addr ;
reg[DATA_WIDTH - 1:0] shiftReg_data, shiftReg_q;
reg[ADDR_WIDTH:0] shiftReg_we = 1'b0; reg shiftReg_we_enable = 1'b0;
reg shiftReg_ce = 1'b0;
reg[DEPTH - 1:0] mOutPtr = 0;
reg empty_n = 1'b1; reg full_n = 1'b1;
wire[ADDR_WIDTH - 1:0] shiftReg_addr_next;
wire[DATA_WIDTH - 1:0] shiftReg_data_next;
wire shiftReg_we_next;
wire shiftReg_ce_next;
wire[DEPTH - 1:0] mOutPtr_next;
wire empty_n_next;
wire full_n_next;
