wire if_full_n_next;
wire[DATA_WIDTH - 1:0] shiftReg_q_next;

assign shiftReg_data = shiftReg_q;
assign shiftReg_addr = mOutPtr[DEPTH - 2:0];
assign shiftReg_ce = shiftReg_we[0] & shiftReg_we_enable;
assign shiftReg_we[0] = if_write;
assign shiftReg_addr_next = mOutPtr[DEPTH - 2:0] + 32'd1;
assign shiftReg_data_next = if_din;
