    else begin
        shiftReg_q <= shiftReg_q_next;
        shiftReg_we_enable <= shiftReg_we_next;
        mOutPtr <= mOutPtr_next;
        empty_n <= empty_n_next;
        full_n <= full_n_next;
    end
end

