assign shiftReg_ce_next = shiftReg_ce_next;
assign shiftReg_we_next = shiftReg_we_next;
assign shiftReg_data_next = shiftReg_data_next;
assign shiftReg_addr_next = shiftReg_addr_next;

assign full_n = full_n_next;
