			2'b00 : begin
				Shift_clk <= 1'b0;
				Sample_clk <= 1'b0;
			end
			2'b01 : begin
				Shift_clk <= 1'b0;
				Sample_clk <= 1'b1;
			end
			2'b10 : begin
				Shift_clk <= 1'b1;
				Sample_clk <= 1'b0;
			end
			2'b11 : begin
				Shift_clk <= 1'b1;
				Sample_clk <= 1'b1;
			end
