module zmc2_dot(
	input CLK_12M,
	input EVEN,
	input LOAD,
	input H,
	input [31:0] CR,
	output reg [3:0] GAD, GBD,
	output reg DOTA, DOTB
);
reg [31:0] SR;
	always @(negedge CLK_12M) begin
		if (LOAD) begin
			SR <= CR;
		end
		if (H) begin
			SR[31:24] <= SR[23:8];
			SR[23:16] <= SR[15:0];
			SR[15:8] <= SR[7:0];
			SR[7:0] <= SR[31:24];
		end
		else begin
			SR[31:24] <= SR[23:8];
			SR[23:16] <= SR[15:0];
			SR[15:8] <= SR[7:0];
			SR[7:0] <= SR[31:24];
		end
	end
	always @(SR) begin
		GAD[3:0] <= SR[31:28];
		GBD[3:0] <= SR[27:24];
	end
	assign DOTA = GAD[3] | GAD[2] | GAD[1] | GAD[0];
	assign DOTB = GBD[3] | GBD[2] | GBD[1] | GBD[0];
endmodule

