module bus_mux (din,sel,dout);

input [TOTAL_DAT-1 : 0] din;
input [SEL_WIDTH-1:0] sel;
output [DAT_WIDTH-1:0] dout;
parameter DAT_WIDTH = 32;
parameter SEL_WIDTH = 2;
parameter TOTAL_DAT = 32;

wire [DAT_WIDTH-1:0] dout;
wire [DAT_WIDTH-1:0] din_temp [2**SEL_WIDTH-1:0];
wire [DAT_WIDTH-1:0] dout_temp [2**SEL_WIDTH-1:0];

genvar i;
generate
	for (i = 0; i < 2**SEL_WIDTH; i = i + 1) begin : gen1
		assign din_temp[i] = din[(i*DAT_WIDTH)+:DAT_WIDTH];
	end
endgenerate

genvar j;
generate
	for (j = 0; j < 2**SEL_WIDTH; j = j + 1) begin : gen2
		assign dout_temp[j] = dout[(j*DAT_WIDTH)+:DAT_WIDTH];
	end
endgenerate

genvar k;
generate
	for (k = 0; k < 2**SEL_WIDTH; k = k + 1) begin : gen3
		assign dout = dout_temp[sel];
	end
endgenerate

endmodule

