module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);
reg [counterSize-1:0] counts [numOfCounters-1:0];
   reg [counterSize-1:0] terminalCounts [numOfCounters-1:0];
   wire [counterSize-1:0] enable [numOfCounters-1:0];
   assign enable[0] = 1'b1;
   assign outCount = counts[numOfCounters-1];
   genvar i;
   generate
      for (i = 0; i < numOfCounters-1; i = i + 1) begin : genCounter
         Counter #(
            .counterSize(counterSize)
         ) counter (
            .clk(clk),
            .reset(reset),
            .count(counts[i]),
            .enable(terminalCounts[i]),
            .outCount(counts[i+1])
         );
      end
   endgenerate
   always @(posedge clk) begin
      if (reset) begin
         for (i = 0; i < numOfCounters; i = i + 1) begin
            counts[i] <= 0;
            terminalCounts[i] <= 0;
         end
      end
      else begin
         for (i = 0; i < numOfCounters; i = i + 1) begin
            if (i == 0) begin
               terminalCounts[i] <= 1'b1;
            end
            else begin
               terminalCounts[i] <= enable[i-1];
            end
            counts[i] <= counts[i-1] + 1;
         end
      end
   end
endmodule

