module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] hsize=640;
parameter [31:0] vsize=480;
parameter [31:0] hfront=16;
parameter [31:0] hback=48;
parameter [31:0] vfront=10;
parameter [31:0] vback=33;
reg [9:0] h_count_reg;
reg [9:0] v_count_reg;
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      h_count_reg <= 10'b0000000000;
      v_count_reg <= 10'b0000000000;
    end
    else begin
      h_count_reg <= h_count_reg + 10'b0000000001;
      v_count_reg <= v_count_reg + 10'b0000000001;
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
  assign active = (h_count_reg < (hsize - hback - hfront)) && (v_count_reg < (vsize - vback - vfront));
  assign hsync = (h_count_reg < hfront) || (h_count_reg >= (hsize - hback - hfront));
  assign vsync = (v_count_reg < vfront) || (v_count_reg >= (vsize - vback - vfront));
endmodule

