module TopModule(
    input  clk,
    input  areset,
    input  x,
    output z
);
localparam [1:0] A = 2'b00, B = 2'b01;
    reg [1:0] state, next;
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= A;
        end else begin
            state <= next;
        end
    end
    always @(*) begin
        next = state;
        case (state)
            A: begin
                if (x) begin
                    next = B;
                end
            end
            B: begin
                if (x) begin
                    next = B;
                end
                else begin
                    next = A;
                end
            end
        endcase
    end
    assign z = state[0];
endmodule

