module TopModule(
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);
reg [2:0] s_prev;
    reg fr2_prev;
    reg fr1_prev;
    reg fr0_prev;
    reg dfr_prev;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            s_prev <= 3'b000;
            fr2_prev <= 1'b0;
            fr1_prev <= 1'b0;
            fr0_prev <= 1'b0;
            dfr_prev <= 1'b0;
        end else begin
            s_prev <= s;
            fr2_prev <= fr2;
            fr1_prev <= fr1;
            fr0_prev <= fr0;
            dfr_prev <= dfr;
        end
    end
    always @(*) begin
        fr2 <= 1'b0;
        fr1 <= 1'b0;
        fr0 <= 1'b0;
        dfr <= 1'b0;
        if (s[2]) begin
            fr2 <= 1'b1;
        end else if (s[1] && !s[0]) begin
            fr1 <= 1'b1;
        end else if (s[0]) begin
            fr0 <= 1'b1;
        end
        if (s[2] && !s_prev[2]) begin
            dfr <= 1'b1;
        end else if (s[1] && !s_prev[1]) begin
            dfr <= 1'b1;
        end else if (s[0] && !s_prev[0]) begin
            dfr <= 1'b1;
        end
    end
endmodule

