  localparam [1:0] B = 2'b01;
  localparam [1:0] C = 2'b10;
  localparam [1:0] D = 2'b11;
  reg [1:0] state;
  reg [1:0] next;
  always @(posedge clk or posedge areset) begin
    if (arst) begin
      state <= A;
    end else begin
      state <= next;
    end
  end
  always @(state or x) begin
    next = state;
    case (state)
      A: begin
        if (x) begin
          next = B;
        end
      end
      B: begin
        if (x) begin
          next = B;
        end
        else begin
          next = C;
        end
      end
      C: begin
        if (x) begin
          next = D;
        end
      end
      D: begin
        if (x) begin
          next = D;
        end
        else begin
          next = A;
        end
      end
      default: begin
        next = state;
      end
    endcase
  end
  assign z = state[0];
endmodule

