module TopModule (
  input  [99:0] in,
  output [99:0] out_both,
  output [99:0] out_any,
  output [99:0] out_different
);
assign out_both[99] = 1'b0;
  assign out_any[0]   = 1'b0;
  assign out_different[0] = 1'b0;
  genvar i;
  generate
    for (i = 0; i < 100; i = i + 1) begin : gen_out_both
      assign out_both[i] = in[i] & in[i-1];
    end
    for (i = 0; i < 100; i = i + 1) begin : gen_out_any
      assign out_any[i] = in[i] | in[(i+1)%100];
    end
    for (i = 0; i < 100; i = i + 1) begin : gen_out_different
      assign out_different[i] = in[i] ^ in[(i+1)%100];
    end
  endgenerate
endmodule

