module TopModule (
  input  [5:0] y,
  input        w,
  output       Y1,
  output       Y3
);
reg [1:0] Y2;
  reg [1:0] Y4;
  always @(y or w) begin
    case (y[5:0])
      6'b000001: {Y2, Y4} <= 2'b00;
      6'b000010: {Y2, Y4} <= 2'b01;
      6'b000100: {Y2, Y4} <= 2'b10;
      6'b001000: {Y2, Y4} <= 2'b11;
      6'b010000: {Y2, Y4} <= 2'b00;
      6'b100000: {Y2, Y4} <= 2'b01;
    endcase
  end
  assign Y1 = Y2[0];
  assign Y3 = Y4[0];
endmodule

module TopModule (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output out
);
always @(*) begin
    case (state)
      2'b00: begin
        next_state = 2'b00;
        out = 1'b0;
      end
      2'b01: begin
        next_state = 2'b01;
        out = 1'b0;
      end
      2'b10: begin
        next_state = 2'b10;
        out = 1'b0;
      end
      2'b11: begin
        next_state = 2'b11;
        out = 1'b1;
      end
    endcase
  end
endmodule

