module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);
reg walk_left;
  reg walk_right;
  reg [1:0] state;
  reg [1:0] next_state;
  always @(posedge clk) begin
    if (areset) begin
      walk_left <= 1'b0;
      walk_right <= 1'b0;
      state <= 2'b00;
    end else begin
      walk_left <= next_state[0];
      walk_right <= next_state[1];
      state <= next_state;
    end
  end
  always @(state, bump_left, bump_right) begin
    next_state[0] = state[0];
    next_state[1] = state[1];
    case (state)
      2'b00: begin
        next_state[0] = 1'b0;
        next_state[1] = 1'b0;
        if (bump_left) begin
          next_state[0] = 1'b1;
        end
        if (bump_right) begin
          next_state[1] = 1'b1;
        end
      end
      2'b01: begin
        next_state[0] = 1'b0;
        next_state[1] = 1'b0;
        if (bump_left) begin
          next_state[1] = 1'b1;
        end
        if (bump_right) begin
          next_state[0] = 1'b1;
        end
      end
      2'b10: begin
        next_state[0] = 1'b0;
        next_state[1] = 1'b0;
        if (bump_left) begin
          next_state[0] = 1'b1;
        end
        if (bump_right) begin
          next_state[1] = 1'b1;
        end
      end
      2'b11: begin
        next_state[0] = 1'b0;
        next_state[1] = 1'b0;
        if (bump_left) begin
          next_state[1] = 1'b1;
        end
        if (bump_right) begin
          next_state[0] = 1'b1;
        end
      end
      default: begin
        next_state[0] = 1'b0;
        next_state[1] = 1'b0;
      end
    endcase
  end
  assign walk_left = state[0];
  assign walk_right = state[1];
endmodule

module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output done
);
reg [2:0] state;
  reg [7:0] byte;
  reg done_reg;
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      byte <= 8'b00000000;
      done_reg <= 1'b0;
    end else begin
      if (state == 3'b000) begin
        if (in[3]) begin
          state <= 3'b001;
          byte <= in;
        end
      end else if (state == 3'b001) begin
        if (in[3]) begin
          state <= 3'b010;
          byte <= in;
        end
      end else if (state == 3'b010) begin
        if (in[3]) begin
          state <= 3'b011;
          byte <= in;
        end
      end else if (state == 3'b011) begin
        if (in[3]) begin
          state <= 3'b000;
          done_reg <= 1'b1;
        end
      end
    end
  end
  assign done = done_reg;
endmodule

module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);
localparam [1:0] S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;
  reg [1:0] state, next;
  always @(posedge clk or negedge aresetn) begin
    if (!arstn) begin
      state <= S0;
    end
    else begin
      state <= next;
    end
  end
  always @(state, x) begin
    case (state)
      S0: begin
        if (x) begin
          next = S1;
        end
        else begin
          next = S0;
        end
      end
      S1: begin
        if (x) begin
          next = S2;
        end
        else begin
          next = S0;
        end
      end
      S2: begin
        if (x) begin
          next = S3;
        end
        else begin
          next = S0;
        end
      end
      S3: begin
        if (x) begin
          next = S3;
        end
        else begin
          next = S0;
        end
      end
      default: next = S0;
    endcase
  end
  always @(state) begin
    case (state)
      S0: z <= 1'b0;
      S1: z <= 1'b0;
      S2: z <= 1'b0;
      S3: z <= 1'b1;
      default: z <= 1'b0;
    endcase
  end
endmodule

